#!/usr/bin/env python3
"""Build a portable, offline dashboard from sibling model/date/run.json files."""
from datetime import datetime, timezone
import json
import hashlib
from pathlib import Path
import re
import base64

HERE = Path(__file__).resolve().parent
# Always score original model responses; edited copies never become predictions.
REFERENCE_DIRS = {'correct', 'corrected', 'reference', 'ground-truth', 'ground_truth', 'gold', 'golden'}
INPUT_GROUPS = [
    {'id':'english', 'name':'English only', 'short':'EN', 'tasks':[1,3,6,8], 'color':'#547ab9'},
    {'id':'english_asian', 'name':'English + Asian text with Western numerals', 'short':'EN+AS', 'tasks':[1,2,3,6,8], 'color':'#be823e'},
    {'id':'japanese', 'name':'Japanese', 'short':'JP', 'tasks':[4,5,7], 'color':'#469776'},
]

def input_group_scores(tasks):
    scores = {}
    by_id = {task['task']:task for task in tasks}
    for group in INPUT_GROUPS:
        selected = [by_id[number]['evaluation'] for number in group['tasks']]
        content = sum(t['content']['f1'] for t in selected)/len(selected)
        numbers = sum(t['numbers']['f1'] for t in selected)/len(selected)
        scores[group['id']] = {'content':content, 'number':numbers, 'overall':(content+numbers)/2}
    return scores

def object_value(value):
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except (ValueError, TypeError):
            return {}
    if isinstance(value, list):
        value = value[-1] if value else {}
    return value if isinstance(value, dict) else {}

def collect(embed_images=False):
    runs = []
    for manifest in sorted(HERE.glob('*/*/run.json')):
        if any(part.lower() in REFERENCE_DIRS for part in manifest.relative_to(HERE).parts):
            continue
        run = json.loads(manifest.read_text())
        # Publish finished trials; a pending response is not an extraction failure.
        if run.get('status') == 'running':
            continue
        name = manifest.parent.parent.name
        backend = run.get('backend', 'Codex fresh subagents')
        families = {'gemini':'Gemini', 'claude':'Claude', 'qwen':'Qwen', 'kimi':'Kimi',
                    'deepseek':'DeepSeek', 'mimo':'MiMo', 'nemotron':'NVIDIA', 'muse':'Meta', 'mistral':'Mistral'}
        family = next((family for prefix, family in families.items() if name.startswith(prefix)), 'OpenAI')
        usage_warnings = {item['task']: item for item in run.get('usage_anomalies', [])}
        tasks = []
        for original in run['tasks']:
            raw = {}
            if original.get('raw_stdout'):
                raw_path = manifest.parent / original['raw_stdout']
                if raw_path.exists() and raw_path.stat().st_size:
                    try:
                        raw = object_value(json.loads(raw_path.read_text()))
                    except ValueError:
                        pass
            metadata = {**original.get('response_metadata', {}), **raw}
            provider = object_value(metadata.get('response_json'))
            usage = {**object_value(provider.get('usage')), **object_value(metadata.get('usage'))}
            details = object_value(metadata.get('token_details'))
            output_details = {**object_value(details.get('completion_tokens_details')),
                              **object_value(details.get('output_tokens_details')),
                              **object_value(usage.get('completion_tokens_details')),
                              **object_value(usage.get('output_tokens_details'))}
            thinking = usage.get('thinking_tokens', usage.get('reasoning_output_tokens', output_details.get('thinking_tokens', output_details.get('reasoning_tokens', details.get('thoughtsTokenCount')))))
            input_details = {**object_value(details.get('prompt_tokens_details')),
                             **object_value(details.get('input_tokens_details')),
                             **object_value(usage.get('prompt_tokens_details')),
                             **object_value(usage.get('input_tokens_details'))}
            input_tokens = metadata.get('input_tokens') if metadata.get('input_tokens') is not None else usage.get('input_tokens')
            output_tokens = metadata.get('output_tokens') if metadata.get('output_tokens') is not None else usage.get('output_tokens')
            total_tokens = usage.get('total_tokens')
            if total_tokens is None and input_tokens is not None and output_tokens is not None:
                total_tokens = input_tokens + output_tokens
            provider_time = metadata.get('duration_seconds')
            if provider_time is None and metadata.get('duration_ms') is not None:
                provider_time = metadata['duration_ms'] / 1000
            response = raw.get('response')
            output = response if original.get('status') == 'completed' and isinstance(response, str) and response.strip() else None
            changed = output is not None and original.get('output_sha256') is not None and hashlib.sha256(output.encode()).hexdigest() != original['output_sha256']
            original_output = raw.get('response') if changed and isinstance(raw.get('response'), str) and raw.get('response') else None
            marker_source = original_output if original_output is not None else (output if not changed else None)
            tasks.append({'task': original['task'], 'input': original['input'].split('/')[-1],
                          'status': original.get('status', 'pending'), 'output': output, 'saved_changed': changed, 'original_output': original_output,
                          'output_bytes': len(output.encode()) if output is not None else None,
                          'unreadable': len(re.findall(r'\[\?\]|\[illegible\]', marker_source)) if marker_source is not None else None,
                          'elapsed_seconds': original.get('elapsed_seconds'), 'provider_seconds': provider_time,
                          'input_tokens': input_tokens, 'output_tokens': output_tokens,
                          'cached_input_tokens': usage.get('cached_input_tokens', input_details.get('cached_tokens', details.get('cachedContentTokenCount'))),
                          'reported_cost_usd': usage.get('cost'),
                          'thinking_tokens': thinking, 'total_tokens': total_tokens,
                          'usage_warning': usage_warnings.get(original['task']),
                          'failed_attempts': int(original.get('status') == 'failed') + sum(a.get('status') == 'failed' for a in original.get('previous_attempts', [])),
                          'retry_seconds': sum(a.get('elapsed_seconds', 0) for a in original.get('previous_attempts', []) if a.get('status') == 'failed'),
                          'prompt': original.get('prompt', original.get('agent_prompt', '')),
                          'error': original.get('failure_reason', original.get('error')), 'metadata_path': str(manifest.relative_to(HERE))})
        runs.append({'id': name + '/' + manifest.parent.name, 'name': name, 'date': run.get('date', manifest.parent.name),
                     'model': run.get('model', name), 'family': family, 'backend': backend,
                     'display_name': run.get('display_name'),
                     'effort': run.get('reasoning_effort', 'unspecified'), 'status': run.get('status', 'unknown'),
                     'earlier_prompt': name == 'gpt-6-astra-low', 'tasks': tasks})
    order = {name: i for i, name in enumerate(['gemini-3.8-flash-low', 'gemini-3.8-flash-medium', 'gemini-3.8-flash-high', 'claude-haiku-5.5', 'claude-sonnet-5.5', 'claude-opus-5.5', 'gpt-6-astra-low', 'gpt-6-luna-low', 'gpt-6-luna-medium', 'gpt-6-luna-high', 'gpt-6.1-sol-low', 'gpt-6.1-sol-medium', 'gpt-6.1-sol-high', 'qwen3.5-35b-a3b', 'qwen3.7-flash', 'qwen3.8-flash', 'gpt-6-astra-low-cli', 'gpt-6-luna-low-cli', 'gpt-6-luna-medium-cli', 'gpt-6-luna-high-cli', 'kimi-k3.1-pro', 'deepseek-v4.1-flash-1017', 'mimo-v2.6-pro', 'mimo-v2.6-flash', 'nemotron-3.5-super-vl', 'muse-spark-open', 'mistral-large-4', 'gemini-4-argon', 'gpt-6-astra-high-openrouter'])}
    runs.sort(key=lambda r: (r['date'], order.get(r['name'], 100), r['name']))
    import sys
    sys.path.insert(0, str(HERE.parent))
    from evaluate import evaluate_runs
    evaluation = evaluate_runs(runs)
    for run in runs:
        e = run['evaluation']
        e['macro_overall_f1'] = (e['macro_content_f1'] + e['macro_numeric_f1']) / 2
        e['input_group_f1'] = input_group_scores(run['tasks'])
    from review import annotate
    images = {}
    for run in runs:
        for task in run['tasks']:
            name = task['input']
            task['review'] = annotate(evaluation['references'][name]['text'], task['output'], name)
            if embed_images and name not in images:
                images[name] = 'data:image/png;base64,' + base64.b64encode((HERE.parent/'files'/name).read_bytes()).decode()
    return {'generated_at': datetime.now(timezone.utc).isoformat(), 'runs': runs, 'evaluation': evaluation, 'images':images, 'input_groups':INPUT_GROUPS}

